from solution import greatest_common_divisor
import math

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# --- concrete examples from spec docstring ---

def test_spec_example_3_5():
    assert greatest_common_divisor(3, 5) == 1


def test_spec_example_25_15():
    assert greatest_common_divisor(25, 15) == 5


# --- reference model equivalence ---

@given(
    a=st.integers(min_value=1, max_value=1000),
    b=st.integers(min_value=1, max_value=1000),
)
def test_matches_math_gcd_small(a, b):
    assert greatest_common_divisor(a, b) == math.gcd(a, b)


@given(
    a=st.integers(min_value=1, max_value=10_000),
    b=st.integers(min_value=1, max_value=10_000),
)
def test_matches_math_gcd_medium(a, b):
    assert greatest_common_divisor(a, b) == math.gcd(a, b)


def test_large_disparate_values():
    # Subtraction-based Euclid needs max/min steps; must still be correct.
    assert greatest_common_divisor(1, 1_000_000) == 1
    assert greatest_common_divisor(1_000_000, 1) == 1


def test_large_values_correctness():
    assert greatest_common_divisor(1_000_000, 999_999) == math.gcd(1_000_000, 999_999)
    assert greatest_common_divisor(999_983, 999_979) == 1
    assert greatest_common_divisor(1_000_000, 500_000) == 500_000


# --- divisibility invariant ---

@given(
    a=st.integers(min_value=1, max_value=2000),
    b=st.integers(min_value=1, max_value=2000),
)
def test_result_divides_both_inputs(a, b):
    g = greatest_common_divisor(a, b)
    assert type(g) == int
    assert g >= 1
    assert a % g == 0
    assert b % g == 0


# --- maximality: no larger common divisor exists ---

@given(
    a=st.integers(min_value=1, max_value=200),
    b=st.integers(min_value=1, max_value=200),
)
def test_result_is_greatest_common_divisor(a, b):
    g = greatest_common_divisor(a, b)
    # every common divisor divides g (Bezout characterization check via brute force)
    for d in range(1, g + 1):
        if a % d == 0 and b % d == 0:
            assert d <= g
            assert g % d == 0
    # nothing strictly greater than g and <= min(a,b) divides both
    for d in range(g + 1, min(a, b) + 1):
        assert not (a % d == 0 and b % d == 0)


# --- symmetry / commutativity ---

@given(
    a=st.integers(min_value=1, max_value=2000),
    b=st.integers(min_value=1, max_value=2000),
)
def test_symmetry(a, b):
    assert greatest_common_divisor(a, b) == greatest_common_divisor(b, a)


# --- identity / boundary properties ---

@given(a=st.integers(min_value=1, max_value=5000))
def test_self_gcd_is_self(a):
    assert greatest_common_divisor(a, a) == a


@given(a=st.integers(min_value=1, max_value=5000))
def test_one_is_identity(a):
    assert greatest_common_divisor(1, a) == 1
    assert greatest_common_divisor(a, 1) == 1


@given(n=st.integers(min_value=1, max_value=5000))
def test_consecutive_integers_coprime(n):
    assert greatest_common_divisor(n, n + 1) == 1


def test_min_boundary_1_1():
    assert greatest_common_divisor(1, 1) == 1


def test_prime_inputs():
    assert greatest_common_divisor(13, 17) == 1
    assert greatest_common_divisor(13, 26) == 13
    assert greatest_common_divisor(1009, 1013) == 1


def test_one_divides_pair():
    assert greatest_common_divisor(2, 4) == 2
    assert greatest_common_divisor(6, 10) == 2
    assert greatest_common_divisor(12, 18) == 6
    assert greatest_common_divisor(100, 80) == 20


# --- scaling / multiplicative property ---

@given(
    a=st.integers(min_value=1, max_value=200),
    b=st.integers(min_value=1, max_value=200),
    k=st.integers(min_value=1, max_value=50),
)
def test_scaling_by_k(a, b, k):
    assert greatest_common_divisor(k * a, k * b) == k * greatest_common_divisor(a, b)


# --- associativity with three args via reference ---

@given(
    a=st.integers(min_value=1, max_value=300),
    b=st.integers(min_value=1, max_value=300),
    c=st.integers(min_value=1, max_value=300),
)
def test_associativity(a, b, c):
    left = greatest_common_divisor(greatest_common_divisor(a, b), c)
    right = greatest_common_divisor(a, greatest_common_divisor(b, c))
    assert left == right == math.gcd(math.gcd(a, b), c)


# --- multiples: gcd(a, multiple of a) == a ---

@given(
    a=st.integers(min_value=1, max_value=500),
    m=st.integers(min_value=1, max_value=20),
)
def test_multiple_gcd(a, m):
    assert greatest_common_divisor(a, m * a) == a
    assert greatest_common_divisor(m * a, a) == a


# --- idempotence-like / absorption ---

@given(
    a=st.integers(min_value=1, max_value=1000),
    b=st.integers(min_value=1, max_value=1000),
)
def test_gcd_absorbs_itself(a, b):
    g = greatest_common_divisor(a, b)
    assert greatest_common_divisor(g, a) == g
    assert greatest_common_divisor(g, b) == g
    assert greatest_common_divisor(g, g) == g
